from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, expire_time]
    results = []

    def purge_expired(current_time):
        expired_keys = [k for k, (v, exp) in cache.items() if exp <= current_time]
        for k in expired_keys:
            del cache[k]

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            purge_expired(t)
            if key in cache:
                del cache[key]
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
            cache[key] = [value, t + ttl]
            cache.move_to_end(key)
        elif op[0] == 'get':
            _, t, key = op
            purge_expired(t)
            if key in cache:
                value, exp = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)
        else:
            raise ValueError("Unknown op")

    return results

